function SalonMap({tables,staff,sessions={},layout={},setLayout,editing=false,setEditing,persist,onTable,compact=false,salons=[{id:"principal",name:"Principal"}],setSalons,activeSalon="principal",setActiveSalon,objects=[],setObjects}:any){
 const occupied=(n:string,i:number)=>sessions[n]?.active??(i%3!==0),assigned=(n:string,i:number)=>sessions[n]?.waiter||(occupied(n,i)?staff[i%Math.max(staff.length,1)]:"");
 const free=tables.filter((n:string,i:number)=>!occupied(n,i)).length,occ=Math.round((tables.length-free)/Math.max(tables.length,1)*100),key=(n:string)=>activeSalon+":"+n;
 const pos=(n:string,i:number)=>layout[key(n)]||layout[n]||{x:12+(i%4)*25,y:20+Math.floor(i/4)*30};
 const drag=(e:any,id:string,isObject=false)=>{if(!editing||compact)return;e.preventDefault();e.currentTarget.setPointerCapture?.(e.pointerId);const box=e.currentTarget.parentElement.getBoundingClientRect();let raf=0;const move=(ev:PointerEvent)=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{const x=Math.max(3,Math.min(97,(ev.clientX-box.left)/box.width*100)),y=Math.max(4,Math.min(96,(ev.clientY-box.top)/box.height*100));if(isObject)setObjects((v:any[])=>v.map(o=>o.id===id?{...o,x,y}:o));else setLayout((v:any)=>({...v,[key(id)]:{x,y}}))})};const up=()=>{cancelAnimationFrame(raf);window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",up)};window.addEventListener("pointermove",move,{passive:true});window.addEventListener("pointerup",up,{once:true})};
 const rename=(id:string,name:string)=>setObjects((v:any[])=>v.map(o=>o.id===id?{...o,name}:o));
 const addObject=()=>{const id="obj"+Date.now();setObjects((v:any[])=>[...v,{id,type:"label",name:"Nueva zona",x:50,y:50}])};
 const removeObject=(id:string)=>setObjects((v:any[])=>v.filter(o=>o.id!==id));
 const addSalon=()=>{const id="salon"+Date.now(),name="Salón "+(salons.length+1),v=[...salons,{id,name}];setSalons(v);setActiveSalon(id);persist?.("mesa_salons",v)};
 const save=()=>{persist?.("mesa_salon_layout",layout);persist?.("mesa_salons",salons);persist?.("mesa_salon_objects",objects);setEditing?.(false)};
 return <div className={"salonExperience "+(compact?"compact":"")}><div className="salonHero"><div><span>MAPA OPERATIVO</span><h2>Tu restaurante, de un vistazo.</h2><p>{editing?"Mové mesas y sectores, editá sus nombres, agregá o eliminá zonas hasta replicar tu restaurante.":"Ubicación, disponibilidad y mozo asignado en tiempo real."}</p></div>{!compact&&<button className={"layoutEdit "+(editing?"saving":"")} onClick={()=>editing?save():setEditing?.(true)}>{editing?"Guardar distribución":"Editar distribución"}</button>}</div>{salons.length>1||editing?<div className="salonSwitcher">{salons.map((r:any)=><button className={activeSalon===r.id?"on":""} key={r.id} onClick={()=>setActiveSalon?.(r.id)}>{editing?<input value={r.name} onClick={e=>e.stopPropagation()} onChange={e=>setSalons((v:any[])=>v.map(x=>x.id===r.id?{...x,name:e.target.value}:x))}/>:r.name}</button>)}{editing&&<button className="addSalon" onClick={addSalon}>+ Agregar salón</button>}</div>:null}<div className="salonMetrics"><article><small>DISPONIBILIDAD</small><b>{free}</b><span>mesas libres ahora</span></article><article><small>OCUPACIÓN</small><b>{occ}%</b><span>{tables.length-free} de {tables.length} mesas</span><i><em style={{width:occ+"%"}}/></i></article><article><small>RESPUESTA PROMEDIO</small><b>1m 08s</b><span>14 s más rápido hoy</span></article><article><small>HORA PICO ESTIMADA</small><b>21:10</b><span>88% ocupación proyectada</span></article></div><div className={"floorPlan newPlan "+(editing?"isEditing":"")}>{objects.map((o:any)=><div key={o.id} style={{left:o.x+"%",top:o.y+"%"}} className={"floorObject "+o.type} onPointerDown={e=>drag(e,o.id,true)}>{editing?<><input value={o.name} onPointerDown={e=>e.stopPropagation()} onChange={e=>rename(o.id,e.target.value)}/><button onPointerDown={e=>e.stopPropagation()} onClick={()=>removeObject(o.id)}>×</button></>:<>{o.type==="kitchen"&&<ChefHat/>}{o.name}{o.type==="entrance"&&<ArrowRight/>}</>}</div>)}{tables.map((n:string,i:number)=>{const busy=occupied(n,i),p=pos(n,i),w=assigned(n,i);return <button style={{left:p.x+"%",top:p.y+"%","--delay":(i*.035)+"s"} as any} className={"floorTableV2 "+(busy?"busy":"free")} key={n} onPointerDown={e=>drag(e,n)} onClick={()=>!editing&&onTable?.(n)}><div className="tableShape"><span>{n}</span><b>{busy?"Ocupada":"Libre"}</b></div><small>{busy?(w||"Sin asignar"):"Disponible"}</small></button>})}{editing&&<><button className="addFloorObject" onClick={addObject}>+ Agregar sector</button><div className="editHint">Arrastrá mesas y sectores · tocá los nombres para editarlos</div></>}</div></div>}

function PaymentFlow({method,setMethod,cash,setCash,splitCash,setSplitCash,tip,setTip,onConfirm}:any){const total=34600,change=method==="cash"?Math.max(0,cash-total-tip):0;return <div className="paymentFlow"><span className="payEyebrow">TOTAL DE LA MESA</span><h3>$34.600</h3><p>¿Cómo vas a pagar?</p><div className="payMethods">{[["cash","Efectivo"],["transfer","Transferencia"],["split","Una parte y una parte"]].map(x=><button key={x[0]} className={method===x[0]?"on":""} onClick={()=>{setMethod(x[0]);setTip(0)}}>{x[1]}</button>)}</div>{method==="cash"&&<label>¿Con cuánto pagás?<div className="moneyInput">$ <input type="number" value={cash||""} onChange={e=>setCash(Number(e.target.value))} placeholder="Ej. 40000"/></div>{cash>=total&&<small>Tu vuelto base es <b>{"$"+(cash-total).toLocaleString("es-AR")}</b></small>}</label>}{method==="split"&&<label>Parte en efectivo<div className="moneyInput">$ <input type="number" max={total} value={splitCash||""} onChange={e=>setSplitCash(Math.min(total,Number(e.target.value)))}/></div><small>Transferencia: <b>{"$"+Math.max(0,total-splitCash).toLocaleString("es-AR")}</b></small></label>}{method&&<div className="tipChoice"><b>¿Querés dejarle propina a Juan?</b><div>{[0,2000,5000].map(n=><button key={n} className={tip===n?"on":""} onClick={()=>setTip(n)}>{n===0?"Sin propina":"$"+n.toLocaleString("es-AR")}</button>)}</div><label>Otro monto<input type="number" value={tip||""} onChange={e=>setTip(Math.max(0,Number(e.target.value)))}/></label>{method==="cash"&&cash>=total+tip&&<small>Vuelto final: <b>{"$"+change.toLocaleString("es-AR")}</b></small>}</div>}<button className="phoneBtn" disabled={!method||(method==="cash"&&cash<total+tip)} onClick={onConfirm}>Confirmar y llamar a Juan</button></div>}
function PremiumReport({range,setRange,customDate,setCustomDate,calendarOpen,setCalendarOpen}:any){const printReport=()=>{const html=document.getElementById("premiumReport")?.innerHTML||"",f=document.createElement("iframe");f.style.cssText="position:fixed;width:0;height:0;border:0";document.body.appendChild(f);const d=f.contentDocument!;d.open();d.write("<html><head><title>Reporte La Esquina</title><style>@page{size:A4;margin:15mm}body{font-family:Arial;color:#111}.reportBrand{border-bottom:2px solid #111;padding-bottom:14px;margin-bottom:22px}.reportBrand h3{font-size:28px;margin:4px 0}.reportKpis{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.reportKpis article,.cashBox,.paymentBreakdown,.reportInsight{border:1px solid #bbb;border-radius:12px;padding:14px}.reportKpis b{font-size:24px;display:block}.financeGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.paymentLine{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #ddd}.cashFlow{font-size:30px;font-weight:bold}.reportInsight{margin-top:10px;background:#f5f5f5}small,span{color:#666}</style></head><body>"+html+"</body></html>");d.close();setTimeout(()=>{f.contentWindow?.focus();f.contentWindow?.print();setTimeout(()=>f.remove(),1000)},150)};return <div className="premiumReportWrap"><div className="reportToolbar"><div>{["Hoy","7 días","Mes","Año"].map(r=><button key={r} className={range===r?"on":""} onClick={()=>setRange(r)}>{r}</button>)}<button className={range==="Personalizado"?"on":""} onClick={()=>setCalendarOpen(!calendarOpen)}>Personalizado</button>{calendarOpen&&<AppCalendar value={customDate} onSelect={(v:string)=>{setCustomDate(v);setRange("Personalizado");setCalendarOpen(false)}} onClose={()=>setCalendarOpen(false)}/>}</div><button className="dark" onClick={printReport}>Generar reporte PDF</button></div><section id="premiumReport" className="premiumReport"><div className="reportBrand"><span>CIERRE DE OPERACIÓN · {range==="Personalizado"?customDate:range.toUpperCase()}</span><h3>La Esquina</h3><small>Resumen financiero y operativo</small></div><div className="reportKpis"><article><span>Ventas netas</span><b>$1.840.500</b><em>+12,8% vs período anterior</em></article><article><span>Tickets</span><b>124</b><small>Ticket promedio · $14.842</small></article><article><span>Clientes</span><b>286</b><small>6,4% más</small></article><article><span>Propinas</span><b>$147.000</b><small>Distribuidas por mozo</small></article></div><div className="financeGrid"><div className="paymentBreakdown"><span>MEDIOS DE PAGO</span>{[["Efectivo","$966.300 · 52,5%"],["Transferencia","$874.200 · 47,5%"]].map(x=><div className="paymentLine" key={x[0]}><b>{x[0]}</b><span>{x[1]}</span></div>)}</div><div className="cashBox"><span>FLUJO DE CAJA</span><div className="cashFlow">$819.300</div><div className="paymentLine"><span>Ventas totales</span><b>$1.840.500</b></div><div className="paymentLine"><span>− Transferencias</span><b>$874.200</b></div><div className="paymentLine"><span>− Propinas a repartir</span><b>$147.000</b></div><div className="paymentLine finalCash"><span>Efectivo final en caja</span><b>$819.300</b></div></div></div><div className="reportInsight"><b>Control de cierre</b><p>124 cuentas cerradas · 0 cuentas abiertas · 0 diferencias registradas.</p><small>Efectivo final = ventas totales − transferencias − propinas. Los pagos combinados se distribuyen entre efectivo y transferencia.</small></div></section></div>}
function AppCalendar({value,onSelect,onClose}:any){return <div className="mesaCalendar tipCalendar"><div><b>Octubre 2026</b><button onClick={onClose}>×</button></div><div className="week">{["L","M","X","J","V","S","D"].map(x=><span key={x}>{x}</span>)}</div><div className="days">{Array.from({length:31},(_,i)=>i+1).map(n=>{const v="2026-10-"+String(n).padStart(2,"0");return <button key={n} className={value===v?"sel":""} onClick={()=>onSelect(v)}>{n}</button>})}</div></div>}
function ProductDialog({product,onClose,onSave}:any){const [name,setName]=useState(product?.name||""),[category,setCategory]=useState(product?.category||"Principales"),[price,setPrice]=useState(product?.price||""),[stock,setStock]=useState(product?.stock??20),[options,setOptions]=useState<any[]>(product?.options||[]),[optionName,setOptionName]=useState(""),[optionPrice,setOptionPrice]=useState("");const addOption=()=>{if(!optionName.trim())return;setOptions(v=>[...v,{id:Date.now(),name:optionName.trim(),price:Number(optionPrice)||0}]);setOptionName("");setOptionPrice("")};return <div className="appDialog productDialog"><div><button className="x" onClick={onClose}>×</button><span className="tag">{product?"EDITAR PRODUCTO":"NUEVO PRODUCTO"}</span><h2>{product?"Actualizar producto":"Agregar al menú"}</h2><label>Nombre<input value={name} onChange={e=>setName(e.target.value)}/></label><div className="productFields"><label>Categoría<input value={category} onChange={e=>setCategory(e.target.value)}/></label><label>Precio base<input type="number" value={price} onChange={e=>setPrice(e.target.value)}/></label><label>Stock disponible<input type="number" min="0" value={stock} onChange={e=>setStock(Number(e.target.value))}/></label></div><div className="optionBuilder"><div><b>Opciones del producto</b><small>Ej.: Combo grande, Combo chico, con papas, doble carne.</small></div>{options.map((o:any)=><div className="optionRow" key={o.id}><span><b>{o.name}</b><small>{o.price>0?"+ $"+o.price.toLocaleString("es-AR"):"Sin adicional"}</small></span><button onClick={()=>setOptions(v=>v.filter(x=>x.id!==o.id))}>Eliminar</button></div>)}<div className="optionInputs"><input placeholder="Nombre de la opción" value={optionName} onChange={e=>setOptionName(e.target.value)}/><input type="number" placeholder="$ adicional" value={optionPrice} onChange={e=>setOptionPrice(e.target.value)}/><button onClick={addOption}>+ Agregar opción</button></div></div><button className="dark wide" onClick={()=>name&&Number(price)>0&&onSave({...(product||{}),name,category,price:Number(price),stock:Number(stock),options,active:Number(stock)>0?(product?.active??true):false})}>Guardar y publicar</button></div></div>}
function KitchenBoard({orders,setOrders,notify,onReady}:any){const ping=()=>{try{const C=(window.AudioContext||(window as any).webkitAudioContext),c=new C(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=880;g.gain.setValueAtTime(.12,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.45);o.start();o.stop(c.currentTime+.45)}catch{}};const items=(o:any)=>[o.main,...String(o.extra||"").split(" · ").filter(Boolean)];const readyItem=(o:any,item:string)=>{const done=[...(o.readyItems||[])];if(!done.includes(item))done.push(item);setOrders((os:any[])=>os.map(x=>x.id===o.id?{...x,readyItems:done}:x));onReady?.({id:o.id+"-"+item,table:o.table,text:item+" listo para retirar"});ping();notify("Mesa "+o.table+" · "+item+" listo")};const advance=(o:any)=>{const next=(o.status==="Nuevo"||o.status==="En cola")?"Preparando":"Listo";setOrders((os:any[])=>os.map(x=>x.id===o.id?{...x,status:next}:x));if(next==="Listo"){onReady?.({id:o.id+"-all",table:o.table,text:"Pedido completo listo para retirar"});ping();notify("Mesa "+o.table+" · pedido completo listo")}else notify("Mesa "+o.table+" en preparación")};const printTicket=(o:any)=>{const f=document.createElement("iframe");f.style.cssText="position:fixed;width:0;height:0;border:0";document.body.appendChild(f);const d=f.contentDocument!;d.open();d.write("<html><head><title>Comanda</title><style>@page{margin:8mm}body{font-family:Arial;padding:8px;width:280px}h1{font-size:24px;border-bottom:2px dashed #000;padding-bottom:12px}.items{font-size:18px;line-height:1.7;margin:24px 0}</style></head><body><h1>LA ESQUINA · COCINA</h1><b>MESA "+o.table+" · "+o.time+"</b><div class=\"items\"><b>"+o.main+"</b><br/>"+o.extra+"</div><small>Comanda #"+o.id+"</small></body></html>");d.close();setTimeout(()=>{f.contentWindow?.focus();f.contentWindow?.print();setTimeout(()=>f.remove(),1000)},120)};return <div className="kitchenPage"><div className="kitchenHead"><div><span>COCINA EN VIVO</span><h2>Comandas</h2><p>Marcá platos individuales o el pedido completo cuando estén listos.</p></div><b>● {orders.filter((o:any)=>o.status!=="Listo").length} activas</b></div><div className="kitchenGrid">{orders.map((o:any)=><article key={o.id} className={o.status==="Listo"?"ready":""}><header><b>Mesa {o.table}</b><span>{o.time}</span></header><div className="kitchenItems">{items(o).map((item:string)=><button key={item} className={(o.readyItems||[]).includes(item)?"itemReady":""} disabled={(o.readyItems||[]).includes(item)||o.status==="Listo"} onClick={()=>readyItem(o,item)}><span>{item}</span><b>{(o.readyItems||[]).includes(item)?"Listo ✓":"Marcar listo"}</b></button>)}</div><small>{o.status.toUpperCase()}</small><div className="kitchenActions"><button onClick={()=>advance(o)} disabled={o.status==="Listo"}>{o.status==="Listo"?"Pedido listo ✓":o.status==="Preparando"?"Pedido completo listo":"Preparar pedido"}</button><button onClick={()=>printTicket(o)}>Imprimir ticket</button></div></article>)}</div></div>}

function AliasManager({aliases,setAliases,persist,notify}:any){const [name,setName]=useState(""),[holder,setHolder]=useState(""),[cuit,setCuit]=useState(""),[limit,setLimit]=useState("");const save=()=>{if(!name.trim()||!holder.trim()||!cuit.trim()||Number(limit)<=0)return;const v=[...aliases,{id:Date.now(),name:name.trim(),holder:holder.trim(),cuit:cuit.trim(),limit:Number(limit),used:0,active:true}];setAliases(v);persist("mesa_aliases",v);setName("");setHolder("");setCuit("");setLimit("");notify("Alias agregado")};return <div className="aliasManager"><div className="menuManagerHead"><div><span className="tag">COBROS POR TRANSFERENCIA</span><h3>Alias</h3><p>Definí titular, CUIT y cuánto puede recibir cada alias. Al alcanzar el límite deja de ofrecerse en caja.</p></div></div><div className="aliasGrid">{aliases.map((a:any)=>{const left=Math.max(0,a.limit-a.used);return <article key={a.id} className={left<=0?"disabled":""}><small>ALIAS</small><h3>{a.name}</h3><div className="aliasIdentity"><strong>{a.holder||"Titular no configurado"}</strong><span>CUIT {a.cuit||"—"}</span></div><b>{"$"+left.toLocaleString("es-AR")}</b><span>disponibles de {"$"+a.limit.toLocaleString("es-AR")}</span><div className="aliasProgress"><i style={{width:Math.min(100,a.used/a.limit*100)+"%"}}/></div></article>})}<article className="aliasAdd"><small>NUEVO ALIAS</small><input placeholder="ej. caja.restaurante" value={name} onChange={e=>setName(e.target.value)}/><input placeholder="Nombre del titular" value={holder} onChange={e=>setHolder(e.target.value)}/><input placeholder="CUIT · ej. 20-12345678-9" value={cuit} onChange={e=>setCuit(e.target.value)}/><input type="number" placeholder="Límite disponible" value={limit} onChange={e=>setLimit(e.target.value)}/><button disabled={!name.trim()||!holder.trim()||!cuit.trim()||Number(limit)<=0} onClick={save}>Agregar alias</button></article></div></div>}

function BillingDesk({products,setProducts,aliases,setAliases,staff,notify,persist}:any){const [client,setClient]=useState(""),[cart,setCart]=useState<any[]>([]),[cash,setCash]=useState(0),[aliasId,setAliasId]=useState<number|undefined>(),[transfer,setTransfer]=useState(0),[pick,setPick]=useState<any>(null);const total=cart.reduce((sum:any,p:any)=>sum+p.price,0),remaining=Math.max(0,total-cash-transfer),available=aliases.filter((a:any)=>a.active&&a.limit-a.used>0);const add=(p:any)=>{if(p.options?.length)setPick(p);else setCart(v=>[...v,{...p,lineId:Date.now()+Math.random()}])};const addOption=(p:any,o:any)=>{setCart(v=>[...v,{...p,name:p.name+" · "+o.name,price:p.price+(o.price||0),lineId:Date.now()+Math.random()}]);setPick(null)};const charge=()=>{if(total<=0||remaining>0||cash+transfer!==total)return;const a=aliases.find((x:any)=>x.id===aliasId);if(transfer>0&&(!a||transfer>a.limit-a.used))return;let next=aliases;if(a&&transfer>0){next=aliases.map((x:any)=>x.id===a.id?{...x,used:x.used+transfer,active:x.used+transfer<x.limit}:x);setAliases(next);persist("mesa_aliases",next);const updated=next.find((x:any)=>x.id===a.id);if(updated&&!updated.active)notify("Alias "+updated.name+" alcanzó su límite y fue deshabilitado")}const waiter=[...staff].sort((x:any,y:any)=>x.length-y.length)[0]||"Sin asignar";notify("Venta registrada · sincronizada con reportes · mesa asignada a "+waiter);const sold:any={};cart.forEach((p:any)=>sold[p.id]=(sold[p.id]||0)+1);const pv=products.map((p:any)=>sold[p.id]?{...p,stock:Math.max(0,Number(p.stock??99)-sold[p.id]),active:Math.max(0,Number(p.stock??99)-sold[p.id])>0}:p);setProducts(pv);persist("mesa_products",pv);printSaleTicket(client||"Consumidor final",cart,total,cash,transfer);setClient("");setCart([]);setCash(0);setTransfer(0);setAliasId(undefined)};return <div className="billingPage"><div className="billingHead"><div><span>FACTURACIÓN</span><h2>Nueva venta</h2><p>Menú sincronizado con administración. El nombre del cliente no se guarda.</p></div><div className="billingTotal"><small>TOTAL</small><b>{"$"+total.toLocaleString("es-AR")}</b></div></div><div className="billingLayout"><section><label>Cliente<input value={client} onChange={e=>setClient(e.target.value)} placeholder="Nombre del cliente"/></label><h3>Menú disponible</h3><div className="billingProducts">{products.filter((p:any)=>p.active&&Number(p.stock??1)>0).map((p:any)=><button key={p.id} onClick={()=>add(p)}><span><b>{p.name}</b><small>{p.category}{p.options?.length?" · "+p.options.length+" opciones":""}</small></span><strong>{"$"+p.price.toLocaleString("es-AR")}</strong><Plus/></button>)}</div></section><aside><h3>Cuenta</h3>{cart.map((p:any)=><div className="billLine" key={p.lineId}><span>{p.name}</span><b>{"$"+p.price.toLocaleString("es-AR")}</b><button onClick={()=>setCart(v=>v.filter(x=>x.lineId!==p.lineId))}>×</button></div>)}{!cart.length&&<p className="emptyBill">Seleccioná productos del menú.</p>}<div className="billingPay"><label>Efectivo<input type="number" value={cash||""} onChange={e=>setCash(Math.min(total,Number(e.target.value)))}/></label><label>Transferencia<input type="number" value={transfer||""} onChange={e=>setTransfer(Math.min(Math.max(0,total-cash),Number(e.target.value)))}/></label>{transfer>0&&<><label>Alias<select value={aliasId||""} onChange={e=>setAliasId(Number(e.target.value))}><option value="">Seleccionar alias</option>{available.map((a:any)=><option value={a.id} key={a.id}>{a.name} · {a.holder||"Titular sin configurar"} · {"$"+Math.max(0,a.limit-a.used).toLocaleString("es-AR")} disp.</option>)}</select></label>{aliasId&&(()=>{const a=aliases.find((x:any)=>x.id===aliasId);return a?<div className="selectedAlias"><small>TRANSFERIR A</small><b>{a.name}</b><strong>{a.holder||"Titular no configurado"}</strong><span>CUIT {a.cuit||"—"}</span><em>Monto: {"$"+transfer.toLocaleString("es-AR")}</em></div>:null})()}</>}<div className="billingRemaining"><span>Falta cobrar</span><b>{"$"+remaining.toLocaleString("es-AR")}</b></div><button className="dark wide" disabled={!cart.length||total<=0||remaining>0||cash+transfer!==total||(transfer>0&&!aliasId)} onClick={charge}>Cobrar e imprimir</button></div></aside></div>{pick&&<div className="billingOptionModal"><div><button className="x" onClick={()=>setPick(null)}>×</button><small>PERSONALIZAR</small><h3>{pick.name}</h3><button className="optionChoice" onClick={()=>{setCart(v=>[...v,{...pick,lineId:Date.now()+Math.random()}]);setPick(null)}}><span>Producto base</span><b>{"$"+pick.price.toLocaleString("es-AR")}</b></button>{pick.options.map((o:any)=><button className="optionChoice" key={o.id} onClick={()=>addOption(pick,o)}><span>{o.name}</span><b>{o.price?"+ $"+o.price.toLocaleString("es-AR"):"Sin adicional"}</b></button>)}</div></div>}</div>}
function printSaleTicket(client:string,cart:any[],total:number,cash:number,transfer:number){const f=document.createElement("iframe");f.style.cssText="position:fixed;width:0;height:0;border:0";document.body.appendChild(f);const d=f.contentDocument!;d.open();d.write("<html><head><style>@page{margin:8mm}body{font-family:Arial;width:280px;padding:8px}h1{font-size:22px;border-bottom:2px dashed #000;padding-bottom:10px}.row{display:flex;justify-content:space-between;padding:6px 0}.total{font-size:20px;font-weight:bold;border-top:2px dashed #000;margin-top:12px;padding-top:12px}</style></head><body><h1>LA ESQUINA</h1><b>"+client+"</b><p>"+new Date().toLocaleString("es-AR")+"</p>"+cart.map(p=>"<div class=\"row\"><span>"+p.name+"</span><b>$"+p.price.toLocaleString("es-AR")+"</b></div>").join("")+"<div class=\"row total\"><span>TOTAL</span><b>$"+total.toLocaleString("es-AR")+"</b></div><div class=\"row\"><span>Efectivo</span><b>$"+cash.toLocaleString("es-AR")+"</b></div><div class=\"row\"><span>Transferencia</span><b>$"+transfer.toLocaleString("es-AR")+"</b></div></body></html>");d.close();setTimeout(()=>{f.contentWindow?.focus();f.contentWindow?.print();setTimeout(()=>f.remove(),1000)},120)}
